import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;

public class OrderLog
{
    private ArrayList<Order> orders;

    public OrderLog()
    {
        orders = new ArrayList<>();
    }

    public void addOrder(String customer, String drink)
    {
        orders.add(new Order(customer.trim(), drink.trim().toLowerCase()));
    }

    public int getCount()
    {
        return orders.size();
    }

    public HashMap<String, Integer> countByDrink()
    {
        HashMap<String, Integer> counts = new HashMap<>();
        for(Order order : orders) {
            String drink = order.getDrink();
            int count = counts.getOrDefault(drink, 0);
            counts.put(drink, count + 1);
        }
        return counts;
    }

    public HashSet<String> getCustomers()
    {
        HashSet<String> customers = new HashSet<>();
        for(Order order : orders) {
            customers.add(order.getCustomer());
        }
        return customers;
    }
}

